/* ---- strtod ---- */
double strtod(const char *nptr, char **endptr) {
    const char *p = nptr;
    while (isspace(*p)) p++;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; } else if (*p == '+') p++;
    double val = 0;
    while (*p >= '0' && *p <= '9') { val = val * 10 + (*p - '0'); p++; }
    if (*p == '.') {
        p++;
        double div = 10;
        while (*p >= '0' && *p <= '9') { val += (*p - '0') / div; div *= 10; p++; }
    }
    if (*p == 'e' || *p == 'E') {
        p++;
        int eneg = 0;
        if (*p == '-') { eneg = 1; p++; } else if (*p == '+') p++;
        int exp = 0;
        while (*p >= '0' && *p <= '9') { exp = exp*10 + (*p - '0'); p++; }
        double mult = 1;
        while (exp--) mult *= 10;
        if (eneg) val /= mult; else val *= mult;
    }
    if (endptr) *endptr = (char *)p;
    return neg ? -val : val;
}

